'use strict';
function withinTolerance(actual, expected, epsilon) {
  return Math.abs(actual - expected) <= (epsilon || 1e-9);
}
function assertClose(actual, expected, epsilon) {
  if (!withinTolerance(actual, expected, epsilon)) {
    throw new Error('expected ' + actual + ' near ' + expected);
  }
}
module.exports = { withinTolerance, assertClose };

