'use strict';
function createBarrier(count) {
  let pending = count;
  let resolveAll;
  const done = new Promise((res) => { resolveAll = res; });
  return {
    signal() { if (--pending <= 0) resolveAll(); },
    wait() { return done; },
  };
}
module.exports = { createBarrier };

'use strict';
const path = require('path');
function resolveFromRoot(root, ...segments) {
  return path.resolve(root, ...segments);
}
function isWithin(root, target) {
  const rel = path.relative(root, target);
  return rel && !rel.startsWith('..') && !path.isAbsolute(rel);
}
module.exports = { resolveFromRoot, isWithin };

'use strict';
function topoSort(nodes, edges) {
  const order = [];
  const visited = new Set();
  function visit(n) {
    if (visited.has(n)) return;
    visited.add(n);
    for (const dep of edges[n] || []) visit(dep);
    order.push(n);
  }
  for (const n of nodes) visit(n);
  return order;
}
module.exports = { topoSort };
